import {normalizeName} from './normalize.mjs';
import {validateNormalized,displayNormalized} from './name-core.mjs';
export const validateName=raw=>validateNormalized(normalizeName(raw));
export const displayName=raw=>displayNormalized(normalizeName(raw));
export function processName(raw,options={}){
 const convert=options.normalize===undefined?normalizeName:options.normalize;
 const normalized=convert(raw);const problem=validateNormalized(normalized);
 if(problem!==null)return {ok:false,error:problem};
 return {ok:true,name:normalized,label:displayNormalized(normalized)};
}

